// ---- seed-built cap spots ----
if (S.seedUsed !== P.seed){
  S.seedUsed = P.seed;
  S.spots = [];
  const n = 5 + Math.floor(fr(99)*4);
  for (let i=0;i<n;i++){ S.spots.push({ x:(fr(i*2)-0.5)*1.5, y:-fr(i*2+1)*0.5-0.05, r:0.10+fr(i*3)*0.16 }); }
}

// ---- halftone buffer for riso (seed keyed) ----
if (S.dotKey !== P.seed && sty==='riso'){
