  const R = 300; const g = createGraphics(R,R); g.colorMode(HSB,360,100,100,100); g.clear();
  g.noStroke(); g.fill(0,0,0,40);
  const step = 11;
  for (let y=0;y<R;y+=step){ for (let x=0;x<R;x+=step){ const rr = 2.2 + fr(x*7+y)*2.6; g.ellipse(x+(y/step%2?step/2:0), y, rr, rr); } }
  S.dot = g;
}
const hasDot = sty==='riso' && S.dot;

// ---- rhythm ----
const bt = K.beat*spd;
const step = Math.sin(bt*Math.PI);
const bounce = (0.5 - 0.5*Math.cos(bt*Math.PI*2));
const kick = Math.min(1.2, K.pulse*0.6 + A.bass*0.7);
const sway = Math.sin(bt*Math.PI*0.5);
const air = A.treble||0;

// ---- pose config ----
let legAmp, armBase, armSwing, capAmp, hip;
if (P.pose==='walk'){ legAmp=0.75; armBase=0.35; armSwing=-step*0.6; capAmp=0.14; hip=step*0.06; }
else if (P.pose==='dance'){ legAmp=0.30; armBase=1.7; armSwing=Math.sin(bt*Math.PI)*0.7; capAmp=0.26; hip=sway*0.14; }
else if (P.pose==='spore'){ legAmp=0.14; armBase=1.15; armSwing=Math.sin(bt*Math.PI*0.5)*0.2; capAmp=0.12; hip=sway*0.05; }
else { legAmp=0.13; armBase=0.5; armSwing=step*0.15; capAmp=0.10; hip=sway*0.04; }
legAmp *= (0.6+E*0.7);

// ---- colors by style ----
const capW = 0.75 + P.capW*0.7;
const sl = 0.8 + P.stemLen*0.7;
const chub = 0.7 + P.chub*0.6;
const printSty = (sty==='riso'||sty==='woodcut');

push();
const bobY = -bounce*11*s*E - kick*6*s*E - (0.5+0.5*Math.sin(K.t*0.7))*3*s;
const swayX = sway*13*s*E + hip*width*0.03;
translate(cx + swayX, cy + bobY);
rotate(hip*0.7 + sway*0.04*E);
noStroke();

// ---------- print backing card ----------
