  rectMode(CENTER); rect(0,-14*s, 150*s*capW, 230*s, 8*s); rectMode(CORNER);
  pop();
}

// ---------- helper: heat color for thermal ----------
const heat = (v) => { const cc = constrain(v,0,1); return (cc>0.66)?[55*(1-(cc-0.66)/0.34)+0,90,100]:(cc>0.33)?[20+20*((cc-0.33)/0.33),95,95]:[280-70*(cc/0.33),80,70]; };

// ---------- LEGS ----------
const drawLeg = (sx, ph) => {
  push();
  translate(sx, 34*s);
  rotate(ph*legAmp);
  if (sty==='xray'){ noFill(); stroke(190,60,95,80); strokeWeight(2*s); line(0,0,0,44*s); ellipse(0,50*s,14*s,8*s); noStroke(); }
