  else { fill(45,10,92); ellipse(0,24*s,16*s,46*s); fill(H,55,88); ellipse(2*s,50*s,20*s,9*s); }
  pop();
};
drawLeg(-12*s*chub, step);
drawLeg(12*s*chub, -step);

// ---------- ARMS ----------
const drawArm = (sx, sign, ang) => {
  push();
  translate(sx, -6*s);
  rotate(sign*ang);
  if (sty==='xray'){ noFill(); stroke(190,60,95,80); strokeWeight(2*s); line(0,0,0,40*s); noStroke(); }
