  pop();
};
drawArm(-20*s*chub, -1, armBase - armSwing);
drawArm(20*s*chub, 1, armBase + armSwing);

// ---------- STEM (body) ----------
push();
const bw = 34*s*chub, bh = 44*s*sl;
if (sty==='xray'){
  noFill(); stroke(190,55,95,70); strokeWeight(1.6*s);
  beginShape(); vertex(-bw*0.7,-bh); bezierVertex(-bw,0,-bw*0.8,bh, -bw*0.5,bh); vertex(bw*0.5,bh); bezierVertex(bw*0.8,bh,bw,0,bw*0.7,-bh); endShape(CLOSE);
