} else if (sty==='thermal'){
  const h=heat(0.5); fill(h[0],h[1],h[2]); ellipse(0,0,bw*2,bh*2);
  blendMode(ADD); const hc=heat(0.85); fill(hc[0],hc[1],hc[2],40); ellipse(-3*s,4*s,bw*1.1,bh*1.4); blendMode(BLEND);
} else if (sty==='woodcut'){
  fill(0,0,12); ellipse(0,0,bw*2,bh*2);
  stroke(40,10,90); strokeWeight(1.6*s); noFill();
  for(let i=0;i<4;i++){ arc(-bw*0.3, -bh*0.6+i*bh*0.5, bw*0.9, bh*0.4, PI*0.15, PI*0.85); } noStroke();
} else {
  fill(45,10,92); ellipse(0,0,bw*2,bh*2);
  fill(H,20,60,45); ellipse(7*s,6*s,bw*1.2,bh*1.5);
  fill(45,6,99,55); ellipse(-8*s,-8*s,bw*0.8,bh*0.9);
}
pop();

// ---------- CAP ----------
push();
translate(0,-40*s*sl);
const capWob = Math.sin(bt*Math.PI + 0.5)*capAmp*E + sway*0.05;
rotate(capWob);
const squash = 1 + kick*0.08*E;
const CW = 78*s*capW, CH = 62*s;
const drawCap = () => { beginShape(); vertex(-CW/2,6*s); bezierVertex(-CW/2,-CH*squash,CW/2,-CH*squash,CW/2,6*s); endShape(CLOSE); rect(-CW/2,2*s,CW,10*s,4*s); };
if (sty==='xray'){
  noFill(); stroke(190,60,95,80); strokeWeight(2*s); drawCap();
  strokeWeight(1*s); stroke(190,55,95,45);
  for(let i=0;i<11;i++){ const a=PI+ (i/10)*PI; line(0,4*s, Math.cos(a)*CW*0.46, 4*s+Math.sin(a)*CH*0.7); }
  noStroke();
} else if (sty==='thermal'){
  const h=heat(0.7); fill(h[0],h[1],h[2]); drawCap();
  blendMode(ADD); const hc=heat(0.95); fill(hc[0],hc[1],hc[2],55); ellipse(0,-CH*0.4,CW*0.5,CH*0.5); blendMode(BLEND);
} else if (sty==='woodcut'){
  fill(0,0,12); drawCap();
  fill(40,10,90); for (const sp of S.spots){ ellipse(sp.x*CW*0.5, 4*s+sp.y*CH, sp.r*CW*0.8, sp.r*CH*0.7); }
} else {
  fill(H,68,92); drawCap();
  fill(H,80,70,60); arc(0,6*s,CW,CH*0.7,0.15,PI-0.15,CHORD);
  fill(H,45,99,55); ellipse(-CW*0.18,-CH*0.4,CW*0.42,CH*0.45);
  const spotH = sty==='riso'?185:45;
  fill(spotH,sty==='riso'?45:12,sty==='riso'?85:99);
  for (const sp of S.spots){ ellipse(sp.x*CW*0.5, 4*s+sp.y*CH, sp.r*CW*0.8, sp.r*CH*0.7); }
}
