// ---------- FACE (on stem) ----------
if (sty!=='xray'){
  push();
  translate(0,-6*s*sl);
  const blink = (Math.sin(K.t*1.3)>0.96)?0.2:1;
  if (sty==='thermal'){ const h=heat(0.9); fill(h[0],h[1],h[2]); ellipse(-11*s,-2*s,7*s,9*s*blink); ellipse(11*s,-2*s,7*s,9*s*blink); }
  else if (sty==='woodcut'){ fill(40,10,90); ellipse(-11*s,-2*s,7*s,9*s*blink); ellipse(11*s,-2*s,7*s,9*s*blink); }
  else { fill(0,0,12); ellipse(-11*s,-2*s,7*s,9*s*blink); ellipse(11*s,-2*s,7*s,9*s*blink);
    fill(0,0,100,80); ellipse(-12*s,-3*s,2*s,2*s); ellipse(10*s,-3*s,2*s,2*s);
    fill(H,60,88,60); ellipse(-19*s,8*s,10*s,6*s); ellipse(19*s,8*s,10*s,6*s); }
  if (sty!=='thermal'){ noFill(); stroke(sty==='woodcut'?color(40,10,90):color(0,0,20)); strokeWeight(2.5*s); const sm=0.15+kick*0.2; arc(0,8*s,18*s,12*s*(0.5+sm),0.15,PI-0.15); noStroke(); }
  pop();
