    const sr = (1.5+fr(i*5+2)*3)*s*(1+air*0.7);
    if (sty==='thermal'){ const h=heat(0.6); fill(h[0],h[1],h[2],40*(1-ph)); } else { fill((H+40)%360,40,95,45*(1-ph)); }
    ellipse(sx,syb,sr,sr);
  }
  blendMode(BLEND);
