  const CW2=78*s*capW, CH2=62*s; beginShape(); vertex(-CW2/2,6*s); bezierVertex(-CW2/2,-CH2,CW2/2,-CH2,CW2/2,6*s); endShape(); noStroke(); pop();
}

pop();
blendMode(BLEND);
